CREATE OR REPLACE FUNCTION public.round_up_shift_hours() RETURNS trigger LANGUAGE plpgsql SET search_path TO public AS $$ BEGIN IF NEW.approved_hours IS NOT NULL THEN IF NEW.review_status='reviewed' OR NEW.reviewed_at IS NOT NULL THEN NEW.approved_hours := ceil(NEW.approved_hours*100)/100; ELSIF NEW.approved_hours>=7.51 AND NEW.approved_hours<8 THEN NEW.approved_hours:=8; END IF; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.review_workforce_shift(_shift uuid, _hours numeric, _notes text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public AS $$ DECLARE s public.workforce_shifts; payable numeric; BEGIN IF NOT public.is_admin_or_manager(auth.uid()) OR NOT public.has_workspace_access(auth.uid(),'attendance') THEN RAISE EXCEPTION 'Attendance manager required'; END IF; SELECT * INTO s FROM public.workforce_shifts WHERE id=_shift AND org_id=public.current_org_id() FOR UPDATE; IF s.id IS NULL OR _hours IS NULL OR _hours<0 OR _hours>24 OR _hours::text IN ('NaN','Infinity','-Infinity') OR length(trim(coalesce(_notes,'')))<3 OR length(_notes)>500 THEN RAISE EXCEPTION 'Provide verified hours and a review note'; END IF; IF EXISTS(SELECT 1 FROM public.payroll_payslip_directory p JOIN public.payroll_runs r ON r.id=p.payroll_run_id WHERE p.user_id=s.employee_id AND r.status='approved' AND s.shift_date BETWEEN r.period_start AND r.period_end) THEN RAISE EXCEPTION 'This shift has already been paid'; END IF; payable:=ceil(_hours*100)/100; UPDATE public.workforce_shifts SET approved_hours=payable,review_status='reviewed',reviewed_by=auth.uid(),reviewed_at=now(),review_notes=_notes WHERE id=_shift; UPDATE public.workforce_alerts SET resolved_at=now() WHERE shift_id=_shift AND resolved_at IS NULL; INSERT INTO public.audit_logs(org_id,employee_id,action,details) VALUES(s.org_id,s.employee_id,'attendance_reviewed',jsonb_build_object('shift_id',s.id,'hours',payable,'reviewer',auth.uid())); END $$;